
from taf.sbts.oam.coam.admin.interfaces.admin_21b import SBTS21B
from taf.sbts.oam.coam.admin.interfaces.admin_22r1 import SBTS22R1
from taf.sbts.oam.coam.admin.interfaces.admin_22r2 import SBTS22R2
from taf.sbts.oam.coam.admin.interfaces.admin_22r3 import SBTS22R3
from taf.sbts.oam.coam.admin.interfaces.admin_22r4 import SBTS22R4
from taf.sbts.oam.coam.admin.interfaces.admin_23r1 import SBTS23R1
from taf.sbts.oam.coam.admin.interfaces.admin_23r2 import SBTS23R2
from taf.sbts.oam.coam.admin.interfaces.admin_23r3 import SBTS23R3
from taf.sbts.oam.coam.admin.interfaces.admin_23r4 import SBTS23R4
from taf.sbts.oam.coam.admin.interfaces.admin_24r1 import SBTS24R1
from taf.sbts.oam.coam.admin.interfaces.admin_24r2 import SBTS24R2
from taf.sbts.oam.coam.admin.interfaces.admin_24r3 import SBTS24R3
from taf.sbts.oam.coam.admin.interfaces.admin_25r1 import SBTS25R1
from taf.sbts.oam.coam.admin.interfaces.admin_25r2 import SBTS25R2
from taf.sbts.oam.coam.admin.interfaces.admin_25r3 import SBTS25R3
from taf.sbts.oam.coam.admin.interfaces.admin_26r1 import SBTS26R1
from taf.sbts.oam.coam.admin.interfaces.admin_26r2 import SBTS26R2
from taf.sbts.oam.coam.admin.exceptions import ReleaseNotSupported


class SupportedCaomAdminVersions(object):
    sbts21b = SBTS21B
    sbts22r1 = SBTS22R1
    sbts22r2 = SBTS22R2
    sbts22r3 = SBTS22R3
    sbts22r4 = SBTS22R4
    sbts23r1 = SBTS23R1
    sbts23r2 = SBTS23R2
    sbts23r3 = SBTS23R3
    sbts23r4 = SBTS23R4
    sbts24r1 = SBTS24R1
    sbts24r2 = SBTS24R2
    sbts24r3 = SBTS24R3
    sbts25r1 = SBTS25R1
    sbts25r2 = SBTS25R2
    sbts25r3 = SBTS25R3
    sbts26r1 = SBTS26R1
    sbts26r2 = SBTS26R2


class CoamAdminProvider(object):
    @classmethod
    def get_coam_admin_interface(cls, api_client, release):
        coam_admin_interface = getattr(SupportedCaomAdminVersions, release.lower(), None)
        if not coam_admin_interface:
            error_message = 'This version {} is not supported'.format(coam_admin_interface)
            raise ReleaseNotSupported(error_message)
        coam_admin_obj = coam_admin_interface(api_client)

        return coam_admin_obj
